  const gridPulse = Math.sin(t*2 + Math.floor(sx/gs)*5 + Math.floor(sy/gs)*7)*0.5+0.5;
  const neuralGrid = gridLine * gridPulse;
  const layerOffsets = [0, 8, 16, 24];
  let layerLines = 0;
